import { describe, expect, it } from 'vitest';
import { targetScreenMap } from '../../../../src/domain/diagrams/target-screen-map.js';
import { assembleUx } from '../../../../src/domain/planning/target-ux-assembly.js';
import type { UxDraft } from '../../../../src/domain/planning/target-ux.js';
import { screenCard, shopDraft, shopScreens } from '../../../support/ux-fixtures.js';

// RF-626, RF-508, DEC-134: the target screen map is a Mermaid flowchart generated by code from the
// checked screens; the model never writes Mermaid. Every legacy screen is a node with its decision
// on the edge, every label goes through the one escaping function and nothing is clickable.

const keep = (text: string) => text;

function mapOf(draft: UxDraft = shopDraft(), mask = keep): string {
  return targetScreenMap(assembleUx(draft, shopScreens()).ux, mask);
}

describe('targetScreenMap', () => {
  it('RF-626 draws each legacy screen into the screen that replaces it, with the decision on the edge', () => {
    const lines = mapOf().split('\n');

    expect(lines[0]).toBe('flowchart LR');
    expect(lines).toContain('  l1["SCRN#45;001#58; #47;orders"]');
    expect(lines).toContain('  l1 -->|merged| t1');
    expect(lines).toContain('  l2 -->|merged| t1');
    expect(lines).toContain('  l3 -->|kept| t2');
  });

  it('RF-626 a dropped legacy screen points to one dropped node, in a dashed edge', () => {
    const lines = mapOf().split('\n');

    expect(lines.filter((line) => line.includes('-.->|dropped|'))).toHaveLength(2);
    expect(lines.filter((line) => /^ {2}d\d*\[/u.test(line))).toHaveLength(1);
  });

  it('RF-626 the screens lead to each other as the legacy links say', () => {
    const lines = mapOf().split('\n');

    expect(lines).toContain('  t1 --> t2');
    expect(lines).toContain('  t2 --> t1');
  });
});

describe('targetScreenMap: empty, hostile and masked labels', () => {
  it('RF-626 a map of no screen is a flowchart with no node', () => {
    expect(targetScreenMap(assembleUx(undefined, []).ux, keep)).toBe('flowchart LR\n');
  });

  it('RF-508 a hostile screen name cannot close the label or add a click, a link or a style', () => {
    const hostile = '"] click l1 "javascript:alert(1)" style t1 fill:red;\n %% x <img src=x>';
    const draft: UxDraft = {
      ...shopDraft(),
      screens: [{ name: hostile, purpose: hostile, reason: hostile, cards: ['SCRN-003'] }],
    };
    const cards = [screenCard('SCRN-003', { title: hostile, route: hostile })];

    const map = targetScreenMap(assembleUx(draft, cards).ux, keep);

    expect(map).not.toMatch(/^\s*(click|style|linkStyle|classDef|href)\b/mu);
    expect(map).not.toMatch(/<|javascript:|%%/u);
    expect(map.split('\n').filter((line) => line.includes('"')).length).toBeGreaterThan(0);
    for (const line of map.split('\n')) {
      expect(line.match(/"/gu)?.length ?? 0).toBeLessThanOrEqual(4);
    }
  });

  it('RNF-003 a secret in a label is masked before it is coded', () => {
    const map = mapOf(shopDraft(), (text) => text.replaceAll('Orders', 'MASKED'));

    expect(map).toContain('MASKED');
    expect(map).not.toContain('Orders');
  });
});
